-- =========================================
-- TOON CINEMA - POSTGRESQL DATABASE
-- =========================================

-- 1. Bảng phim
CREATE TABLE IF NOT EXISTS "Movies" (
    "MovieID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" VARCHAR(200) NOT NULL,
    "Genre" VARCHAR(100) NOT NULL,
    "Duration" INTEGER NOT NULL CHECK ("Duration" > 0),
    "ImageUrl" VARCHAR(500),
    "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 2. Bảng phòng chiếu
CREATE TABLE IF NOT EXISTS "Rooms" (
    "RoomID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RoomName" VARCHAR(100) NOT NULL,
    "NumberOfRows" INTEGER NOT NULL DEFAULT 10,
    "SeatPerRow" INTEGER NOT NULL DEFAULT 8
);

-- 3. Bảng lịch chiếu
CREATE TABLE IF NOT EXISTS "Showtimes" (
    "ShowtimeID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "MovieID" INTEGER NOT NULL REFERENCES "Movies"("MovieID"),
    "RoomID" INTEGER NOT NULL REFERENCES "Rooms"("RoomID"),
    "StartTime" TIMESTAMP NOT NULL,
    "TicketPrice" NUMERIC(12,2) NOT NULL DEFAULT 60000
);

-- 4. Bảng ghế đã đặt
CREATE TABLE IF NOT EXISTS "BookedSeats" (
    "BookingID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ShowtimeID" INTEGER NOT NULL REFERENCES "Showtimes"("ShowtimeID"),
    "SeatCode" VARCHAR(5) NOT NULL,
    "CreatedAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE ("ShowtimeID", "SeatCode")
);

-- 5. Thêm 3 phòng chiếu mẫu
-- Chỉ thêm khi bảng Rooms đang trống
INSERT INTO "Rooms" ("RoomName", "NumberOfRows", "SeatPerRow")
SELECT v.name, 10, 8
FROM (
    VALUES
        ('Phòng 1'),
        ('Phòng 2'),
        ('Phòng 3')
) AS v(name)
WHERE NOT EXISTS (
    SELECT 1 FROM "Rooms"
);

-- 6. Kiểm tra kết quả
SELECT * FROM "Rooms";